func _ensure_input_map() -> void:
	for act in ACTIONS:
		if not InputMap.has_action(act):
			InputMap.add_action(act, 0.2)
		for kc in ACTIONS[act]:
			var ev := InputEventKey.new()
			ev.physical_keycode = kc
			InputMap.action_add_event(act, ev)


func _ready() -> void:
	_ensure_input_map()
	if get_tree() != null:
		get_tree().quit_on_go_back = false
	font_reg = load(FONT_REG) as FontFile
	font_bold = load(FONT_BOLD) as FontFile
	font_serif = load(FONT_SERIF) as FontFile
	font_art = load(FONT_ART) as FontFile
	font_display = load(FONT_DISPLAY) as FontFile
	if font_display != null: font_display.fallbacks = [font_serif, font_reg]
	if font_reg == null:
		push_warning("Noto Sans SC Regular 加载失败")
	if font_bold == null:
		font_bold = font_reg
	if font_serif == null:
		font_serif = font_bold
	elif font_bold != null:
		# 不常见字符交给完整黑体字库，保持字形覆盖。
		font_serif.fallbacks = [font_bold]
	if font_art == null:
		font_art = font_serif
	else:
		font_art.fallbacks = [font_serif, font_reg]
	_tune_font_rendering()
	_interface_theme = Readability.theme_for_text()
	get_tree().node_added.connect(_on_ui_node_added)
	_load_roles()
	_load_save()
	ensure_starter_buildings()
	_apply_mouse_cursor()
	# 预热浮层贴图：第一次 G.veil() 走 _build_vignette_tex / _build_hatch_tex，
	# 各 new 一张 Gradient/ImageTexture 会花掉 ~50ms，让 VerifyPerf 的"首开浮层"
	# 直接踩预算。在这里跑一次以后所有面板首开都拿缓存，零开销。
	_build_vignette_tex()
	_build_hatch_tex()


func _notification(what: int) -> void:
	if what == NOTIFICATION_WM_GO_BACK_REQUEST:
		trigger_cancel()


func _exit_tree() -> void:
	# The platform cursor otherwise retains its texture beyond RenderingServer.
	if DisplayServer.get_name() != "headless":
		Input.set_custom_mouse_cursor(null)


## 移动端 / 触控触发 ESC（ui_cancel）：发送标准 ESC 按键事件，走完整 _input -> _gui_input -> _unhandled_input 传播链
func trigger_cancel() -> void:
	if GmConsole != null and GmConsole.visible:
		GmConsole.close()
		return
	var ev_down := InputEventKey.new()
	ev_down.keycode = KEY_ESCAPE
	ev_down.physical_keycode = KEY_ESCAPE
	ev_down.pressed = true
	var ev_up := InputEventKey.new()
	ev_up.keycode = KEY_ESCAPE
	ev_up.physical_keycode = KEY_ESCAPE
	ev_up.pressed = false
	var vp := get_viewport()
	if vp != null:
		vp.push_input(ev_down)
		vp.push_input(ev_up)
	else:
		Input.parse_input_event(ev_down)
		Input.parse_input_event(ev_up)
		Input.flush_buffered_events()


## Smooth sampling is applied separately to text nodes; art textures remain pixel sharp.
func _tune_font_rendering() -> void:
	for f in [font_reg, font_bold, font_serif, font_art, font_display]:
		if f == null:
			continue
		f.subpixel_positioning = TextServer.SUBPIXEL_POSITIONING_AUTO
		f.force_autohinter = false
		f.hinting = TextServer.HINTING_NONE if _is_small_face(f) else TextServer.HINTING_LIGHT
		f.antialiasing = TextServer.FONT_ANTIALIASING_GRAY
		f.oversampling = 2.0


func _on_ui_node_added(node: Node) -> void:
	if node is Label or node is Button or node is LineEdit or node is RichTextLabel or node is TextEdit:
		_apply_ui_text.call_deferred(weakref(node))


func _apply_ui_text(reference: WeakRef) -> void:
	var node := reference.get_ref() as Node
	if node != null: Readability.apply_to(node)


func register_ui_page(parent: Node) -> void:
